import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val a = IntArray(6)
    for (i in 0..5) {
        a[i] = scanner.nextInt()
    }

    val b = IntArray(10)
    for (i in 0..5) {
        val x = a[i]
        b[x]++
    }

    var y = 0
    var no = 0

    for (i in 1..9) {
        when {
            b[i] == 4 -> {
                for (j in 1..9) {
                    if (b[j] == 2) {
                        y++
                    }
                }
            }
            b[i] > 4 -> {
                if (b[i] == 6) {
                    y++
                }
            }
            else -> {
                no++
            }
        }
    }

    if (no == 9) {
        println("Alien")
    } else {
        if (y == 1) {
            println("Elephant")
        } else {
            println("Bear")
        }
    }
}

